<script>(()=>{document.querySelectorAll('[data-admin-panel="catalog"] article').forEach((card,index)=>{const image=card.querySelector(':scope > div:first-child > img'),input=card.querySelector('input[type="file"][name="image"]');if(!image||!input)return;input.id=`product-photo-${index}`;const frame=document.createElement('div');frame.className='relative h-20 w-20 shrink-0 overflow-hidden rounded-xl bg-slate-200';image.before(frame);image.className='h-full w-full object-cover';frame.append(image);const actions=document.createElement('div');actions.className='absolute inset-x-1 bottom-1 flex justify-end gap-1';actions.innerHTML=`<a href="${image.src}" download title="Unduh foto" aria-label="Unduh foto" class="grid h-8 w-8 place-items-center rounded-lg bg-white/95 text-slate-800 shadow"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3v12m0 0 4-4m-4 4-4-4M5 21h14"/></svg></a><label for="${input.id}" title="Ganti foto" aria-label="Ganti foto" class="grid h-8 w-8 cursor-pointer place-items-center rounded-lg bg-emerald-700 text-white shadow"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg></label>`;frame.append(actions)});})();</script>
<script>(()=>{const tabs=document.querySelectorAll('[data-admin-tab]'),panels=document.querySelectorAll('[data-admin-panel]');function activate(name){tabs.forEach(tab=>{const active=tab.dataset.adminTab===name;tab.classList.toggle('border-emerald-700',active);tab.classList.toggle('text-emerald-800',active);tab.classList.toggle('border-transparent',!active);tab.classList.toggle('text-slate-500',!active)});panels.forEach(panel=>panel.classList.toggle('hidden',panel.dataset.adminPanel!==name));history.replaceState(null,'',name==='orders'?location.pathname+location.search:'#'+name)}tabs.forEach(tab=>tab.addEventListener('click',()=>activate(tab.dataset.adminTab)));if(['#catalog','#agents','#production-data'].includes(location.hash))activate(location.hash.slice(1));document.querySelector('[data-print-production]')?.addEventListener('click',()=>window.print());document.querySelectorAll('[data-copy-link]').forEach(button=>button.addEventListener('click',async()=>{await navigator.clipboard.writeText(button.dataset.copyLink);button.textContent='Tersalin ✓';setTimeout(()=>button.textContent='Salin',1500)}));document.querySelectorAll('[data-order-toggle]').forEach(button=>button.addEventListener('click',()=>{const detail=button.closest('[data-order-group]').querySelector('[data-order-detail]'),open=detail.classList.toggle('hidden')===false;button.setAttribute('aria-expanded',open);button.textContent=open?'Tutup':'Detail'}))})();</script>
@endsection
